raw=b'"""P1-E2E-01 \xed\x9a\x8c\xea\xb7\x80 \xec\x8b\x9c\xed\x97\x98(#20) \xec\x9a\x94\xec\xb2\xad\xc2\xb7\xed\x8c\x90\xec\xa0\x95 \xeb\x8f\x84\xea\xb5\xac \xe2\x80\x94 2\xed\x9a\x8c\xec\xb0\xa8(10/5 \xec\x9d\xb4\xeb\xaf\xb8\xec\xa7\x80 \xec\xa0\x84\xed\x99\x98 \xeb\x92\xa4)\xec\x9a\xa9.\n\n\xec\x8b\xa4\xed\x96\x89 \xec\x9c\x84\xec\xb9\x98: edge01(\xec\x9a\x94\xec\xb2\xad). \xed\x91\x9c\xec\xa4\x80 \xeb\x9d\xbc\xec\x9d\xb4\xeb\xb8\x8c\xeb\x9f\xac\xeb\xa6\xac\xeb\xa7\x8c \xec\x93\xb4\xeb\x8b\xa4(Python 3.6 \xec\x9d\xb4\xec\x83\x81).\n  python3 rg.py run <OUT_DIR>                  \xea\xb8\xb0\xec\xa4\x80 \xed\x8c\x8c\xec\x9d\xbc\xec\x9d\x84 \xeb\xa8\xbc\xec\xa0\x80 \xec\x93\xb0\xea\xb3\xa0 \xec\xbc\x80\xec\x9d\xb4\xec\x8a\xa4 \xec\x9a\x94\xec\xb2\xad\xec\x9d\x84 \xeb\xb3\xb4\xeb\x82\xb8 \xeb\x92\xa4 \xed\x8c\x90\xec\xa0\x95\xed\x95\x9c\xeb\x8b\xa4.\n  python3 rg.py judge <OUT_DIR>                \xec\xa0\x80\xec\x9e\xa5\xeb\x90\x9c results.jsonl\xeb\xa1\x9c \xeb\x8b\xa4\xec\x8b\x9c \xed\x8c\x90\xec\xa0\x95\xed\x95\x9c\xeb\x8b\xa4(\xec\x9a\x94\xec\xb2\xad \xec\x97\x86\xec\x9d\x8c).\n  python3 rg.py crosscheck <OUT_DIR> <DB_LOG>  db01 \xec\xa1\xb0\xed\x9a\x8c \xea\xb2\xb0\xea\xb3\xbc\xec\x99\x80 API \xec\x9d\x91\xeb\x8b\xb5\xec\x9d\x84 transaction_id\xeb\xa1\x9c \xeb\x8c\x80\xec\xa1\xb0\xed\x95\x9c\xeb\x8b\xa4(\xec\x9a\x94\xec\xb2\xad \xec\x97\x86\xec\x9d\x8c).\n\nrun\xec\x9d\x80 \xeb\xa9\x88\xec\xb6\xa4 \xec\xa1\xb0\xea\xb1\xb4\xec\x9d\xb4 \xec\x9e\x88\xeb\x8b\xa4(fail-close):\n- OUT_DIR\xec\x97\x90 \xed\x8c\x8c\xec\x9d\xbc\xec\x9d\xb4 \xec\x9e\x88\xec\x9c\xbc\xeb\xa9\xb4 \xec\x8b\x9c\xec\x9e\x91\xed\x95\x98\xec\xa7\x80 \xec\x95\x8a\xeb\x8a\x94\xeb\x8b\xa4(\xea\xb8\xb0\xeb\xa1\x9d \xeb\x8d\xae\xec\x96\xb4\xec\x93\xb0\xea\xb8\xb0 \xeb\xb0\xa9\xec\xa7\x80).\n- \xec\x9a\x94\xec\xb2\xad \xec\xa0\x84\xec\x97\x90 Worker 3\xeb\x8c\x80 /readyz\xea\xb0\x80 \xeb\xaa\xa8\xeb\x91\x90 200\xec\x9d\xb4 \xec\x95\x84\xeb\x8b\x88\xeb\xa9\xb4 \xec\x9a\xb4\xec\x98\x81 DB\xec\x97\x90 \xec\x93\xb0\xea\xb8\xb0 \xec\xa0\x84\xec\x97\x90 \xeb\xa9\x88\xec\xb6\x98\xeb\x8b\xa4.\n- \xec\x9d\x91\xeb\x8b\xb5\xec\x9d\xb4 5xx\xec\x9d\xb4\xea\xb1\xb0\xeb\x82\x98 \xec\x97\xb0\xea\xb2\xb0\xec\x97\x90 \xec\x8b\xa4\xed\x8c\xa8\xed\x95\x98\xeb\xa9\xb4 \xeb\x82\xa8\xec\x9d\x80 \xec\x9a\x94\xec\xb2\xad\xec\x9d\x84 \xeb\xb3\xb4\xeb\x82\xb4\xec\xa7\x80 \xec\x95\x8a\xeb\x8a\x94\xeb\x8b\xa4. \xec\x9e\xac\xec\x8b\x9c\xeb\x8f\x84\xed\x95\x98\xec\xa7\x80 \xec\x95\x8a\xeb\x8a\x94\xeb\x8b\xa4(\xec\xa4\x91\xeb\xb3\xb5 \xed\x96\x89 \xeb\xb0\xa9\xec\xa7\x80).\n\xec\xa2\x85\xeb\xa3\x8c \xec\xbd\x94\xeb\x93\x9c: 0 = \xed\x8c\x90\xec\xa0\x95 \xeb\x8c\x80\xec\x83\x81 \xec\xa0\x84\xeb\xb6\x80 PASS, 1 = FAIL \xec\x9e\x88\xec\x9d\x8c, 2 = \xec\xa4\x91\xeb\x8b\xa8(STOP) \xeb\x98\x90\xeb\x8a\x94 \xec\x82\xac\xec\x9a\xa9 \xec\x98\xa4\xeb\xa5\x98.\n"""\nimport hashlib\nimport http.client\nimport json\nimport os\nimport re\nimport sys\nimport time\nfrom datetime import datetime, timedelta, timezone\n\nTARGETS = (\'10.1.93.105\', \'10.1.93.107\', \'10.1.93.108\')\nPORT = 30080\nTIMEOUT = 10\nSOURCE_IP = \'198.51.100.10\'  # \xeb\xac\xb8\xec\x84\x9c\xec\x9a\xa9 IP\nKST = timezone(timedelta(hours=9))\nR02, R04 = frozenset({\'R02\'}), frozenset({\'R04\'})\nNONE = frozenset()\n\n\ndef cases(run_id, today):\n    """(\xec\xbc\x80\xec\x9d\xb4\xec\x8a\xa4 ID, \xec\x9a\x94\xec\xb2\xad \xeb\xb3\xb8\xeb\xac\xb8, \xea\xb8\xb0\xeb\x8c\x80\xea\xb0\x92). \xea\xb8\xb0\xeb\x8c\x80\xea\xb0\x92: Rule \xec\xa7\x91\xed\x95\xa9 | \'HTTP422\' | \'INFO\'. \xec\x88\x9c\xec\x84\x9c\xeb\x8c\x80\xeb\xa1\x9c \xeb\xb3\xb4\xeb\x82\xb8\xeb\x8b\xa4."""\n    def body(kind, amount, account, occurred_at=None):\n        b = {\'account_id\': f\'SIM_rg_{run_id}_{account}\', \'amount\': amount, \'currency\': \'KRW\',\n             \'transaction_type\': kind, \'source_ip\': SOURCE_IP}\n        if occurred_at:\n            b[\'occurred_at\'] = occurred_at\n        return b\n\n    t0230, t0500 = f\'{today}T02:30:00+09:00\', f\'{today}T05:00:00+09:00\'\n    out = [(\'P01\', body(\'deposit\', 10000, \'P01\'), NONE),\n           (\'P02\', body(\'deposit\', 3000000, \'P02\'), R02)]\n    out += [(f\'P03-{i}\', body(\'withdrawal\', 10000, \'P03\'), frozenset({\'R01\'}) if i == 4 else NONE) for i in range(1, 5)]\n    out += [(f\'P04-{i}\', body(\'transfer\', 700000, \'P04\'), frozenset({\'R07\'}) if i == 4 else NONE) for i in range(1, 5)]\n    out += [(\'P05\', body(\'deposit\', 1500000, \'P05\', t0230), R04),\n            (\'N01\', body(\'deposit\', 2999999, \'N01\'), NONE),\n            (\'N02\', body(\'deposit\', 1500000, \'N02\', t0500), NONE),\n            (\'N03\', body(\'deposit\', 999999, \'N03\', t0230), NONE)]\n    out += [(f\'N04-{i}\', body(\'transfer\', 100000, \'N04\'), NONE) for i in range(1, 5)]\n    out += [(f\'N05-{i}\', body(\'deposit\', 10000, \'N05\'), NONE) for i in range(1, 5)]\n    n07 = body(\'deposit\', 10000, \'N07\')\n    del n07[\'amount\']\n    out += [(\'N06\', body(\'refund\', 10000, \'N06\'), \'HTTP422\'),\n            (\'N07\', n07, \'HTTP422\'),\n            (\'I01\', body(\'deposit\', 1500000, \'I01\', f\'{today}T02:30:00\'), \'INFO\')]\n    return out\n\n\ndef criteria_text(run_id, today, tool_sha, targets, port):\n    return \'\\n\'.join([\n        f\'P1-E2E-01 \xed\x9a\x8c\xea\xb7\x80 \xea\xb8\xb0\xec\xa4\x80 (\xec\x8b\x9c\xed\x97\x98 \xec\xa0\x84 \xea\xb8\xb0\xeb\xa1\x9d) RUN={run_id} \xeb\x8f\x84\xea\xb5\xac rg.py SHA-256={tool_sha}\',\n        f\'\xea\xb3\x84\xec\xa0\x95=SIM_rg_{run_id}_<ID> source_ip={SOURCE_IP} \xea\xb2\xbd\xeb\xa1\x9c=edge01->\' + \'/\'.join(targets) + f\':{port} \xec\x88\x9c\xed\x99\x98, \xec\x9e\xac\xec\x8b\x9c\xeb\x8f\x84 \xec\x97\x86\xec\x9d\x8c\',\n        \'P01 deposit 10000 -> 201 \xec\xa0\x84\xeb\xb6\x80 false | P02 deposit 3000000 -> R02\xeb\xa7\x8c | P03 withdrawal 10000 x4 -> 1~3 false, 4\xeb\xb2\x88\xec\xa7\xb8 R01\xeb\xa7\x8c\',\n        f\'P04 transfer 700000 x4 -> 1~3 false, 4\xeb\xb2\x88\xec\xa7\xb8 R07\xeb\xa7\x8c | P05 deposit 1500000 occurred_at {today}T02:30:00+09:00 -> R04\xeb\xa7\x8c\',\n        f\'N01 deposit 2999999 -> false | N02 deposit 1500000 {today}T05:00:00+09:00 -> false | N03 deposit 999999 {today}T02:30:00+09:00 -> false\',\n        \'N04 transfer 100000 x4 -> \xec\xa0\x84\xeb\xb6\x80 false | N05 deposit 10000 x4 -> \xec\xa0\x84\xeb\xb6\x80 false | N06 type=refund -> 422 | N07 amount \xeb\x88\x84\xeb\x9d\xbd -> 422\',\n        f\'I01 deposit 1500000 occurred_at {today}T02:30:00(\xec\x8b\x9c\xea\xb0\x84\xeb\x8c\x80 \xec\x97\x86\xec\x9d\x8c) -> \xed\x8c\x90\xec\xa0\x95 \xec\xa0\x9c\xec\x99\xb8(INFO): \xec\x9d\x91\xeb\x8b\xb5 \xec\xbd\x94\xeb\x93\x9c\xc2\xb7Rule\xc2\xb7DB \xec\xa0\x80\xec\x9e\xa5 \xec\x8b\x9c\xea\xb0\x81\xeb\xa7\x8c \xea\xb8\xb0\xeb\xa1\x9d. 5xx\xc2\xb7\xec\x97\xb0\xea\xb2\xb0 \xec\x8b\xa4\xed\x8c\xa8\xeb\xa9\xb4 FAIL\',\n        \'\xea\xb3\xb5\xed\x86\xb5: 201 \xec\x9d\x91\xeb\x8b\xb5\xec\x9d\x80 fds_evaluation_skipped=false, fds_detected=(\xed\x8a\xb8\xeb\xa6\xac\xea\xb1\xb0 \xec\x9e\x88\xec\x9d\x8c).\',\n        \'Metric \xec\xa6\x9d\xea\xb0\x80(I01 201 \xea\xb8\xb0\xec\xa4\x80): save_success +23, save_failure 0, fds_evaluated +23, fds_detected R01/R02/R07 \xea\xb0\x81 +1,\'\n        \' R04 +1(I01\xec\x9d\xb4 R04\xeb\xa9\xb4 +2), missing_client_ip 0. DB 23\xed\x96\x89. I01\xec\x9d\xb4 422\xeb\xa9\xb4 +22\xc2\xb722\xed\x96\x89.\',\n        \'Critical: \xec\x98\xa4\xed\x83\x90/\xeb\xaf\xb8\xed\x83\x90, 201\xec\x9d\xb8\xeb\x8d\xb0 DB \xeb\xaf\xb8\xec\xa0\x80\xec\x9e\xa5, \xec\x9c\xa0\xed\x9a\xa8 \xec\x9e\x85\xeb\xa0\xa5 5xx. \xec\x8b\x9c\xed\x97\x98 \xec\xa4\x91 Pod restartCount \xeb\xb3\x80\xed\x99\x94 \xec\x97\x86\xec\x9d\x8c.\',\n        \'N08(control01 -> Worker:30080 = 000)\xec\x9d\x80 control01\xec\x97\x90\xec\x84\x9c \xeb\x94\xb0\xeb\xa1\x9c \xed\x99\x95\xec\x9d\xb8\xed\x95\x9c\xeb\x8b\xa4.\',\n    ]) + \'\\n\'\n\n\ndef sha256_file(path):\n    with open(path, \'rb\') as f:\n        return hashlib.sha256(f.read()).hexdigest()\n\n\ndef call(method, target, port, path, payload=None, timeout=TIMEOUT):\n    """(\xec\x83\x81\xed\x83\x9c \xec\xbd\x94\xeb\x93\x9c, \xeb\xb3\xb8\xeb\xac\xb8). \xec\x97\xb0\xea\xb2\xb0 \xec\x8b\xa4\xed\x8c\xa8\xc2\xb7timeout\xec\x9d\x80 (0, \xec\x98\xa4\xeb\xa5\x98 \xec\x9d\xb4\xeb\xa6\x84)."""\n    try:\n        conn = http.client.HTTPConnection(target, port, timeout=timeout)\n        data = None if payload is None else json.dumps(payload, ensure_ascii=False).encode(\'utf-8\')\n        conn.request(method, path, data, {\'Content-Type\': \'application/json\'} if data else {})\n        resp = conn.getresponse()\n        text = resp.read().decode(\'utf-8\', \'replace\')\n        conn.close()\n        return resp.status, text\n    except Exception as e:\n        return 0, type(e).__name__\n\n\ndef load_meta(out_dir):\n    with open(os.path.join(out_dir, \'meta.json\'), encoding=\'utf-8\') as f:\n        meta = json.load(f)\n    current_tool = sha256_file(os.path.abspath(__file__))\n    if meta[\'tool_sha256\'] != current_tool or meta[\'criteria_sha256\'] != sha256_file(os.path.join(out_dir, \'criteria.txt\')):\n        raise ValueError(\'EVIDENCE_BINDING_MISMATCH\')\n    expected = criteria_text(meta[\'run\'], meta[\'today\'], current_tool, meta[\'targets\'], meta[\'port\'])\n    with open(os.path.join(out_dir, \'criteria.txt\'), encoding=\'utf-8\') as f:\n        if f.read() != expected:\n            raise ValueError(\'CRITERIA_METADATA_MISMATCH\')\n    return meta\n\n\ndef judge_one(expect, code, text):\n    """(\xed\x8c\x90\xec\xa0\x95, Rule \xeb\xaa\xa9\xeb\xa1\x9d \xeb\xac\xb8\xec\x9e\x90\xec\x97\xb4). \xed\x8c\x90\xec\xa0\x95: PASS | FAIL | INFO."""\n    if expect == \'HTTP422\':\n        return (\'PASS\' if code == 422 else \'FAIL\'), \'\'\n    trig = None\n    if code == 201:\n        try:\n            j = json.loads(text)\n            if not isinstance(j, dict) or not isinstance(j[\'transaction_id\'], str) or not j[\'transaction_id\']:\n                raise ValueError(\'invalid transaction id\')\n            rules = j[\'fds_rules\']\n            if not isinstance(rules, list) or len(rules) != 4:\n                raise ValueError(\'four rules required\')\n            ids = [r[\'rule_id\'] for r in rules]\n            if any(not isinstance(rid, str) for rid in ids) or set(ids) != {\'R01\', \'R02\', \'R04\', \'R07\'}:\n                raise ValueError(\'rule ids must be unique and complete\')\n            if any(type(r[\'triggered\']) is not bool for r in rules):\n                raise ValueError(\'triggered must be boolean\')\n            trig = sorted(r[\'rule_id\'] for r in rules if r[\'triggered\'])\n            skipped, detected = j[\'fds_evaluation_skipped\'], j[\'fds_detected\']\n            if type(detected) is not bool or skipped is not False or detected != bool(trig):\n                raise ValueError(\'invalid normal evaluation flags\')\n        except (ValueError, KeyError, TypeError):\n            return \'FAIL\', \'invalid-json\'\n    if expect == \'INFO\':\n        if code == 0 or code >= 500:\n            return \'FAIL\', \'\'\n        return \'INFO\', \'\' if trig is None else \',\'.join(trig)\n    if trig is None:\n        return \'FAIL\', \'\'\n    good = set(trig) == set(expect) and detected == bool(expect) and skipped is False\n    return (\'PASS\' if good else \'FAIL\'), \',\'.join(trig)\n\n\ndef load_results(out_dir, meta, complete=False):\n    """Reject ambiguous evidence before writing a new judgement. No network calls."""\n    expected = {cid for cid, _, _ in cases(meta[\'run\'], meta[\'today\'])}\n    got, transaction_ids = {}, set()\n    with open(os.path.join(out_dir, \'results.jsonl\'), encoding=\'utf-8\') as f:\n        for line in f:\n            r = json.loads(line)\n            if not isinstance(r, dict) or r.get(\'case\') not in expected or r[\'case\'] in got:\n                raise ValueError(\'CASE_DUPLICATE_OR_UNKNOWN\')\n            if type(r.get(\'http\')) is not int or not isinstance(r.get(\'body\'), str) or not isinstance(r.get(\'worker\'), str):\n                raise ValueError(\'RECORD_INVALID\')\n            if r[\'worker\'] not in meta[\'targets\'] or not (r[\'http\'] == 0 or 100 <= r[\'http\'] <= 599):\n                raise ValueError(\'RECORD_TARGET_OR_STATUS_INVALID\')\n            if r[\'http\'] == 201:\n                j = json.loads(r[\'body\'])\n                if not isinstance(j, dict) or not isinstance(j.get(\'transaction_id\'), str) or not j[\'transaction_id\']:\n                    raise ValueError(\'TRANSACTION_ID_INVALID\')\n                tid = j[\'transaction_id\']\n                if tid in transaction_ids:\n                    raise ValueError(\'TRANSACTION_ID_DUPLICATE\')\n                transaction_ids.add(tid)\n            got[r[\'case\']] = r\n    if complete and set(got) != expected:\n        raise ValueError(\'CASE_RECORDS_INCOMPLETE\')\n    return got\n\n\ndef judge(out_dir, emit=print):\n    try:\n        meta = load_meta(out_dir)\n        got = load_results(out_dir, meta)\n    except (OSError, ValueError, KeyError, TypeError) as e:\n        emit(\'STOP EVIDENCE_INVALID \' + type(e).__name__)\n        return 2\n    counts = {\'PASS\': 0, \'FAIL\': 0, \'INFO\': 0}\n    lines = []\n    for cid, _, expect in cases(meta[\'run\'], meta[\'today\']):\n        r = got.get(cid)\n        if r is None:\n            verdict, rules, worker, code = \'FAIL\', \'NOT_SENT\', \'-\', \'-\'\n        else:\n            verdict, rules = judge_one(expect, r[\'http\'], r[\'body\'])\n            worker, code = r[\'worker\'], r[\'http\']\n        counts[verdict] += 1\n        lines.append(f\'{verdict} {cid} {worker} {code} {rules}\'.rstrip())\n    lines.append(f"== {counts[\'PASS\']} PASS / {counts[\'FAIL\']} FAIL / {counts[\'INFO\']} INFO (\xed\x8c\x90\xec\xa0\x95 \xeb\x8c\x80\xec\x83\x81 {counts[\'PASS\'] + counts[\'FAIL\']}\xea\xb1\xb4)")\n    with open(os.path.join(out_dir, \'judge.txt\'), \'w\', encoding=\'utf-8\') as f:\n        f.write(\'\\n\'.join(lines) + \'\\n\')\n    for line in lines:\n        emit(line)\n    return 1 if counts[\'FAIL\'] else 0\n\n\ndef run(out_dir, run_id=None, targets=TARGETS, port=PORT, timeout=TIMEOUT, now=None, emit=print):\n    now = now or datetime.now(KST)\n    run_id = run_id or now.strftime(\'%Y%m%d%H%M\')\n    today = now.strftime(\'%Y-%m-%d\')\n    os.makedirs(out_dir, exist_ok=True)\n    if os.listdir(out_dir):\n        emit(f\'STOP OUT_DIR_NOT_EMPTY {out_dir}\')\n        return 2\n    tool_sha = sha256_file(os.path.abspath(__file__))\n    with open(os.path.join(out_dir, \'criteria.txt\'), \'w\', encoding=\'utf-8\') as f:\n        f.write(criteria_text(run_id, today, tool_sha, targets, port))\n    crit_sha = sha256_file(os.path.join(out_dir, \'criteria.txt\'))\n    with open(os.path.join(out_dir, \'criteria.sha256\'), \'w\', encoding=\'utf-8\') as f:\n        f.write(f\'{crit_sha}  criteria.txt\\n\')\n    meta = {\'run\': run_id, \'today\': today, \'tool_sha256\': tool_sha, \'criteria_sha256\': crit_sha,\n            \'targets\': list(targets), \'port\': port, \'criteria_written_epoch\': round(time.time(), 3)}\n    with open(os.path.join(out_dir, \'meta.json\'), \'w\', encoding=\'utf-8\') as f:\n        json.dump(meta, f, ensure_ascii=False)\n    emit(f\'CRITERIA {crit_sha} RUN={run_id} TOOL={tool_sha}\')\n\n    for t in targets:\n        code, _ = call(\'GET\', t, port, \'/readyz\', timeout=timeout)\n        emit(f\'READYZ {t} {code}\')\n        if code != 200:\n            emit(f\'STOP NOT_READY {t} {code}\')\n            return 2\n\n    stop = None\n    with open(os.path.join(out_dir, \'results.jsonl\'), \'a\', encoding=\'utf-8\') as out:\n        for n, (cid, payload, _) in enumerate(cases(run_id, today)):\n            target = targets[n % len(targets)]\n            t0 = time.time()\n            code, text = call(\'POST\', target, port, \'/api/v1/transactions\', payload, timeout)\n            rec = {\'t\': round(t0, 3), \'case\': cid, \'worker\': target, \'http\': code,\n                   \'ms\': round((time.time() - t0) * 1000, 1), \'body\': text}\n            out.write(json.dumps(rec, ensure_ascii=False) + \'\\n\')\n            out.flush()\n            with open(os.path.join(out_dir, f\'{cid}.json\'), \'w\', encoding=\'utf-8\') as f:\n                f.write(text)\n            emit(f\'{time.strftime("%H:%M:%S")} {cid} {target} http={code}\')\n            if code == 0 or code >= 500:\n                stop = f\'STOP HTTP_{code} {cid}\'\n                emit(stop)\n                break\n    rc = judge(out_dir, emit)\n    return 2 if stop else rc\n\n\ndef parse_db_log(path):\n    """db01 \xec\xa1\xb0\xed\x9a\x8c \xec\xb6\x9c\xeb\xa0\xa5: account|transaction_id|type|amount|detected|skipped|rules|occurred_at \xec\xa4\x84\xeb\xa7\x8c \xec\x9d\xbd\xeb\x8a\x94\xeb\x8b\xa4."""\n    rows = {}\n    with open(path, encoding=\'utf-8\') as f:\n        for line in f:\n            p = line.rstrip(\'\\n\').split(\'|\')\n            if p[0].startswith(\'SIM_rg_\'):\n                if len(p) != 8 or not p[1] or p[1] in rows:\n                    raise ValueError(\'DB_ROW_AMBIGUOUS\')\n                rows[p[1]] = p\n    return rows\n\n\ndef crosscheck(out_dir, db_log, emit=print):\n    bad, seen = 0, set()\n    try:\n        meta = load_meta(out_dir)\n        prefix = f"SIM_rg_{meta[\'run\']}_"\n        case_list = cases(meta[\'run\'], meta[\'today\'])\n        payloads = {cid: p for cid, p, _ in case_list}\n        got = load_results(out_dir, meta, complete=True)\n        db = {k: v for k, v in parse_db_log(db_log).items() if v[0].startswith(prefix)}\n        # Matching two empty/malformed sources is not a successful regression.\n        for cid, _, expected in case_list:\n            r = got[cid]\n            if judge_one(expected, r[\'http\'], r[\'body\'])[0] == \'FAIL\':\n                raise ValueError(\'API_CASE_FAILED\')\n        results = [got[cid] for cid, _, _ in case_list]\n    except (OSError, ValueError, KeyError, TypeError):\n        emit(\'STOP EVIDENCE_INVALID\')\n        return 2\n    for r in results:\n        cid = r[\'case\']\n        if r[\'http\'] != 201:\n            emit(f"-- {cid} http={r[\'http\']} (201\xec\x9d\xb4 \xec\x95\x84\xeb\x8b\x88\xeb\xaf\x80\xeb\xa1\x9c DB \xed\x96\x89 \xec\x97\x86\xec\x9d\x8c \xea\xb8\xb0\xeb\x8c\x80)")\n            continue\n        j = json.loads(r[\'body\'])\n        tid = j[\'transaction_id\']\n        seen.add(tid)\n        row = db.get(tid)\n        if row is None:\n            bad += 1\n            emit(f\'NG {cid} {tid} DB \xed\x96\x89 \xec\x97\x86\xec\x9d\x8c\')\n            continue\n        p = payloads[cid]\n        rules = sorted(x[\'rule_id\'] for x in j[\'fds_rules\'] if x[\'triggered\'])\n        want = [p[\'account_id\'], tid, p[\'transaction_type\'], p[\'amount\'],\n                \'t\' if j[\'fds_detected\'] else \'f\', \'t\' if j[\'fds_evaluation_skipped\'] else \'f\', \',\'.join(rules) or \'-\']\n        try:\n            have = [row[0], row[1], row[2], float(row[3]), row[4], row[5], row[6]]\n        except ValueError:\n            bad += 1\n            emit(f\'NG {cid} {tid} DB amount invalid\')\n            continue\n        want[3] = float(want[3])\n        ok = want == have\n        bad += not ok\n        emit(f"{\'OK\' if ok else \'NG\'} {cid} {tid} occurred_at={row[7]}" + (\'\' if ok else f\' want={want} have={have}\'))\n    extra = [v for k, v in db.items() if k not in seen]\n    for v in extra:\n        bad += 1\n        emit(f\'NG \xec\x9d\x91\xeb\x8b\xb5\xec\x97\x90 \xec\x97\x86\xeb\x8a\x94 DB \xed\x96\x89 {v[0]} {v[1]}\')\n    emit(f\'== DB {len(db)}\xed\x96\x89 / \xec\x9d\x91\xeb\x8b\xb5 201 {len(seen)}\xea\xb1\xb4 / \xeb\xb6\x88\xec\x9d\xbc\xec\xb9\x98 {bad}\')\n    return 1 if bad else 0\n\n\ndef main(argv):\n    if len(argv) == 3 and argv[1] == \'run\':\n        return run(argv[2])\n    if len(argv) == 3 and argv[1] == \'judge\':\n        return judge(argv[2])\n    if len(argv) == 4 and argv[1] == \'crosscheck\':\n        return crosscheck(argv[2], argv[3])\n    print(__doc__)\n    return 2\n\n\nif __name__ == \'__main__\':\n    sys.exit(main(sys.argv))\n'
